"""Differential driver: run one named scenario under whatever fsutil is importable."""

from __future__ import annotations

import json
import os
import shutil
import sys
import traceback

import fsutil

import scenarios


def snapshot(root):
    items = []
    for base, dirnames, filenames in os.walk(root, followlinks=False):
        dirnames.sort()
        for d in dirnames:
            p = os.path.join(base, d)
            rel = os.path.relpath(p, root)
            if os.path.islink(p):
                items.append(f"L {rel} -> {os.readlink(p)}")
            else:
                items.append(f"D {rel}")
        for f in sorted(filenames):
            p = os.path.join(base, f)
            rel = os.path.relpath(p, root)
            if os.path.islink(p):
                items.append(f"L {rel} -> {os.readlink(p)}")
            else:
                try:
                    with open(p, "rb") as fh:
                        content = fh.read()
                except OSError as e:
                    content = f"<unreadable {e.__class__.__name__}>".encode()
                items.append(f"F {rel} [{len(content)}] {content!r}")
    items.sort()
    return items


def norm(root, value):
    """Replace absolute root prefix so both runs are comparable."""
    if isinstance(value, str):
        return value.replace(root, "<ROOT>")
    if isinstance(value, (list, tuple)):
        return [norm(root, v) for v in value]
    if isinstance(value, dict):
        return {k: norm(root, v) for k, v in value.items()}
    return repr(value) if not isinstance(value, (int, float, bool, type(None))) else value


def main():
    name = sys.argv[1]
    root = os.path.realpath(sys.argv[2])
    if os.path.exists(root):
        shutil.rmtree(root)
    os.makedirs(root)
    fn = getattr(scenarios, name)
    out = {"scenario": name}
    cwd = os.getcwd()
    try:
        res = fn(fsutil, root)
        out["result"] = norm(root, res)
        out["exc"] = None
    except BaseException as e:  # noqa: BLE001
        out["result"] = None
        out["exc"] = {
            "type": type(e).__name__,
            "mro": [c.__name__ for c in type(e).__mro__[:8]],
            "msg": norm(root, str(e)),
        }
        out["tb"] = norm(root, traceback.format_exc().splitlines()[-3:])
    finally:
        os.chdir(cwd)
    out["tree"] = norm(root, snapshot(root))
    print(json.dumps(out, indent=1, sort_keys=True))


if __name__ == "__main__":
    main()

