import os
import pathlib


def mk(root, *parts):
    p = os.path.join(root, *parts)
    os.makedirs(p, exist_ok=True)
    return p


def mkf(root, rel, content="x"):
    p = os.path.join(root, rel)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, "w") as f:
        f.write(content)
    return p


