    mkf(root, "a/with space/hello world.txt", "sp")
    mkf(root, "a/ünïcodé/файл.txt", "uni")
    mk(root, "a/empty_dir")
    mk(root, "a/b/empty2/empty3")
    return os.path.join(root, "a")


