#!/usr/bin/env python3
"""Run every scenario under both impls and diff the JSON outputs."""

from __future__ import annotations

import inspect
import json
import subprocess
import sys

sys.path.insert(0, "/tmp/adiff")
import scenarios  # noqa: E402

IMPLS = {
    "WS": "/workspace/src",
    "REF017": "/tmp/ref017/src",
}


def run(impl_path, name, root):
    env = {
        "PYTHONPATH": f"{impl_path}:/tmp/adiff",
        "PATH": "/usr/bin:/bin",
        "LC_ALL": "C.UTF-8",
        "LANG": "C.UTF-8",
        "PYTHONHASHSEED": "0",
    }
    p = subprocess.run(
        [sys.executable, "/tmp/adiff/driver.py", name, root],
        capture_output=True,
        text=True,
        env=env,
    )
    if p.returncode != 0:
        return {"FATAL": p.stderr[-2000:]}
    return json.loads(p.stdout)


def main():
    names = [
        n
        for n, f in inspect.getmembers(scenarios, inspect.isfunction)
        if not n.startswith(("mk", "tree_", "_"))
    ]
    only = sys.argv[1:] or None
    if only:
        names = [n for n in names if any(o in n for o in only)]
    diffs = 0
    for name in sorted(names):
        a = run(IMPLS["WS"], name, "/tmp/adiff/run_ws")
        b = run(IMPLS["REF017"], name, "/tmp/adiff/run_ref")
        if a == b:
            continue
        diffs += 1
        print("=" * 70)
        print("DIFF:", name)
        for key in sorted(set(a) | set(b)):
            av, bv = a.get(key, "<absent>"), b.get(key, "<absent>")
            if av != bv:
                print(f"  [{key}]")
                print(f"    WS    : {json.dumps(av, ensure_ascii=False)}")
                print(f"    REF017: {json.dumps(bv, ensure_ascii=False)}")
    print(f"\n{len(names)} scenarios, {diffs} differing")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Report only *substantive* diffs: tree, result, or exception NOT explained
by the FSUtil* -> OSError subclass relationship."""

from __future__ import annotations

import inspect
import json
import subprocess
import sys

sys.path.insert(0, "/tmp/adiff")
import scenarios  # noqa: E402


def run(impl_path, name, root):
    env = {
        "PYTHONPATH": f"{impl_path}:/tmp/adiff",
        "PATH": "/usr/bin:/bin",
        "LC_ALL": "C.UTF-8",
        "LANG": "C.UTF-8",
    }
    p = subprocess.run(
        [sys.executable, "/tmp/adiff/driver.py", name, root],
        capture_output=True, text=True, env=env,
    )
    if p.returncode != 0:
        return {"FATAL": p.stderr[-3000:]}
    return json.loads(p.stdout)


def exc_equiv(a, b):
    if a == b:
        return True
    if a is None or b is None:
        return False
    if a["msg"] != b["msg"]:
        return False
    # WS raising an OSError subclass where ref raised plain OSError is compatible
    return b["type"] in a["mro"]


def main():
    names = sorted(
        n for n, f in inspect.getmembers(scenarios, inspect.isfunction)
        if not n.startswith(("mk", "tree_", "_"))
    )
    only = sys.argv[1:] or None
    if only:
        names = [n for n in names if any(o in n for o in only)]
    diffs = 0
    for name in names:
        a = run("/workspace/src", name, "/tmp/adiff/run_ws")
        b = run("/tmp/ref017/src", name, "/tmp/adiff/run_ref")
        problems = []
        if "FATAL" in a or "FATAL" in b:
            problems.append(("FATAL", a.get("FATAL"), b.get("FATAL")))
        if a.get("tree") != b.get("tree"):
            problems.append(("tree", a.get("tree"), b.get("tree")))
        if a.get("result") != b.get("result"):
            problems.append(("result", a.get("result"), b.get("result")))
        if not exc_equiv(a.get("exc"), b.get("exc")):
            problems.append(("exc", a.get("exc"), b.get("exc")))
        if not problems:
            continue
        diffs += 1
        print("=" * 70)
        print("SUBSTANTIVE DIFF:", name)
        for key, av, bv in problems:
            print(f"  [{key}]")
            print(f"    WS    : {json.dumps(av, ensure_ascii=False)}")
            print(f"    REF017: {json.dumps(bv, ensure_ascii=False)}")
    print(f"\n{len(names)} scenarios, {diffs} substantive diffs")


if __name__ == "__main__":
    main()
